values ('bbbb0002-0000-4000-8000-000000000011', 'en', null, 'Game Design Fundamentals', 'A hands-on first course in how games actually work — rules and feedback, the MDA framework, player motivation and flow, balancing, and playtesting. Built from openly-licensed OER Commons game-design material (CC BY).', null, 'work', 17, true, 'technology', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000011', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A game is best described as a system in which players engage in an artificial conflict, defined by rules, that produces a…","options":["realistic simulation","quantifiable outcome","linear story","physical reward"],"answer":1,"explanation":"Salen and Zimmerman''s definition centers on rules and a quantifiable outcome (win/lose/score) — see ''What makes a game''."},{"prompt":"In the MDA framework, the letters stand for…","options":["Mechanics, Dynamics, Aesthetics","Modes, Difficulty, Achievements","Movement, Damage, Animation","Menus, Dialogue, Art"],"answer":0,"explanation":"MDA = Mechanics, Dynamics, Aesthetics (Hunicke, LeBlanc, Zubek) — see ''The MDA framework''."},{"prompt":"A designer builds a game starting mostly from the… while a player experiences it starting from the…","options":["aesthetics; mechanics","mechanics; aesthetics","dynamics; rules","story; score"],"answer":1,"explanation":"MDA reads in opposite directions for designer and player — see ''The MDA framework''."},{"prompt":"Csikszentmihalyi''s concept of ''flow'' describes the state between…","options":["winning and losing","anxiety and boredom","single- and multiplayer","story and gameplay"],"answer":1,"explanation":"Flow is the channel between too-hard (anxiety) and too-easy (boredom) — see ''Motivation and flow''."},{"prompt":"The tight repeated cycle of act → get feedback → decide again is usually called the…","options":["tech tree","core loop","cutscene","difficulty spike"],"answer":1,"explanation":"The core loop is the moment-to-moment cycle players repeat — see ''What makes a game'' and ''Motivation and flow''."},{"prompt":"A ''difficulty spike'' is a problem mainly because it…","options":["makes the game longer","breaks the smooth ramp of challenge and pushes players out of flow","adds too many rules","removes the win condition"],"answer":1,"explanation":"Spikes interrupt the intended difficulty curve — see ''Balancing and difficulty curves''."},{"prompt":"The single most reliable way to find out whether your game is fun is to…","options":["ask other designers","read reviews of similar games","watch real players play it (playtesting)","add more content"],"answer":2,"explanation":"Playtesting with real players is the core empirical tool of design — see ''Prototyping and playtesting''."},{"prompt":"A ''dominant strategy'' in a game is one that…","options":["is the most fun to use","is always at least as good as every alternative, making other choices pointless","only expert players can find","changes every match"],"answer":1,"explanation":"A dominant strategy collapses meaningful choice and is a balance problem — see ''Balancing and difficulty curves''."},{"prompt":"Good feedback in a game should tell the player…","options":["only whether they finally won","what just happened and how it moved them toward the goal","the developer''s intentions","nothing, to preserve mystery"],"answer":1,"explanation":"Feedback closes the loop by connecting an action to its consequence and to the goal — see ''What makes a game''."}]}'::jsonb, null, 10),
  (2, 'What makes a game: rules, goals, feedback', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Break any game down into its three load-bearing parts — rules, goals, and feedback — and explain how they combine into a loop players want to repeat. Warm-up: think of the last game you played. What were you *trying* to do, and how did you know you were making progress?"},{"heading":"The idea","text":"A game is a system of *rules* that creates an artificial conflict with a *quantifiable outcome*. Three parts do the work. *Rules* define what is allowed and what happens — they constrain action and create the challenge. *Goals* give the player something to want (survive, score, reach the exit) — they supply motivation and a way to measure success. *Feedback* tells the player what their action just did and whether it moved them toward the goal — a score ticks up, an enemy flinches, a door clicks open. Rules, goals, and feedback join into the *core loop*: the short cycle of act → see result → decide again that the player repeats hundreds of times."},{"heading":"Worked example","text":"Take classic *Pac-Man*. Rule: touching a ghost costs a life, but eating a power pellet briefly lets you eat ghosts. Goal: clear every dot on the maze. Feedback: the score jumps, the pellet-eaten ghosts turn blue and flee, a sound plays. Now imagine we *remove the feedback* — no score, no color change, no sound. The rules and goal are untouched, yet the game feels dead: the player can no longer read the consequence of their choices, so the loop stops being satisfying. That thought-experiment shows feedback is not decoration; it is what makes the rules legible."},{"heading":"Your turn","text":"For each, name whether it is a rule, a goal, or feedback: (1) ''reach the flagpole before the timer hits zero'', (2) ''you cannot walk through walls'', (3) ''the coin counter increases and chimes'', (4) ''collect all three keys'', (5) ''the screen flashes red when you take damage''. Answers: (1) goal, (2) rule, (3) feedback, (4) goal, (5) feedback."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing a *goal* with a *rule* — ''don''t touch the lava'' is a rule (a constraint), while ''get to the door'' is the goal (what you want). Mistake: thinking feedback only matters when you win; players need feedback on every action, not just the last one. Exit: (a) Which of the three parts supplies the player''s *motivation*? (b) What is the name of the short act-result-decide cycle players repeat? Answers: the goal; the core loop."}]}'::jsonb, 'Rules constrain, goals motivate, feedback informs — keep those three verbs handy all course.', 12),
  (3, 'Core mechanics and the MDA framework', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use the MDA framework to separate what you *build* from what the player *feels*, and explain why a designer can only change aesthetics indirectly. Warm-up: from the diagnostic, which end of MDA does a designer start from — and which end does a player start from?"},{"heading":"The idea","text":"MDA (Hunicke, LeBlanc, and Zubek) splits a game into three layers. *Mechanics* are the rules and systems you actually author: the pieces, the numbers, the allowed actions. *Dynamics* are the run-time behavior that emerges when players interact with those mechanics over time — the strategies, tensions, and situations no single rule spells out. *Aesthetics* are the emotional responses the game evokes: tension, discovery, camaraderie, triumph. The key insight is directionality: a *designer* works left to right, tuning mechanics and hoping for a feeling; a *player* experiences right to left, feeling the aesthetics first and rarely thinking about the rules. You can only reach the aesthetic you want by adjusting the mechanics beneath it — you cannot ''add fun'' directly."},{"heading":"Worked example","text":"Consider the single mechanic ''each turn, draw one card from a shared deck; if it is a bomb, you are out.'' That lone rule generates rich *dynamics*: players count how many bombs are left, bluff about defusing, and grow tense as the deck thins — none of which is written in the rule. The resulting *aesthetic* is nail-biting suspense. Now improve it: suppose playtesters find the end-game random and unfair. A designer does not tell players ''feel less cheated''; they change a *mechanic* — add a card that lets you peek at the top three cards — which creates a new *dynamic* (informed risk-taking) and shifts the *aesthetic* from luck toward tense skill. That is MDA reasoning: change the layer you can actually touch."},{"heading":"Your turn","text":"Label each as Mechanic, Dynamic, or Aesthetic: (1) ''players start rushing the objective in the last 30 seconds'', (2) ''a captured piece is removed from the board'', (3) ''the feeling of narrow escape after a close match'', (4) ''gravity pulls the block down one row per tick'', (5) ''an unspoken alliance forms against the leader''. Answers: (1) dynamic, (2) mechanic, (3) aesthetic, (4) mechanic, (5) dynamic."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling an emergent behavior a mechanic — ''players form alliances'' is a *dynamic*; the mechanic is whatever rule makes alliances pay off. Mistake: trying to design aesthetics directly (''make it more fun'') instead of adjusting the mechanics that produce the feeling. Exit: (a) Which layer does a designer author directly? (b) Emergent strategies that appear during play belong to which layer? Answers: mechanics; dynamics."}]}'::jsonb, 'Designers build M→D→A; players feel A←D←M. Same chain, opposite directions.', 13),
  (4, 'Player motivation and flow', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain the flow channel and distinguish intrinsic from extrinsic motivation, then use both to judge why a game holds attention. Warm-up: recall a game that felt effortless to keep playing — was the challenge matched to your skill?"},{"heading":"The idea","text":"Csikszentmihalyi''s *flow* is the absorbed state where challenge and skill are balanced. Push challenge above skill and the player feels *anxiety*; drop it below and they feel *boredom*. Because a player''s skill rises as they learn, the challenge must rise with it — flow is a moving channel, not a fixed level. Motivation comes in two kinds. *Intrinsic* motivation is doing the activity because it is satisfying in itself — mastering a move, exploring, solving. *Extrinsic* motivation is doing it for an external reward — points, badges, unlocks. Extrinsic rewards can hook a player early, but games that last usually convert that pull into intrinsic enjoyment of the core loop."},{"heading":"Worked example","text":"A puzzle game opens with three trivial tutorial levels, then jumps to a brutal one — playtesters quit at the jump. Diagnose it with flow: the early levels sit in *boredom* (skill outruns challenge), the fourth spikes into *anxiety* (challenge outruns skill), and nothing lives in the channel between. The improvement is not ''make it easier'' but ''match the ramp to the rising skill curve'': re-order and add levels so difficulty climbs in small steps that track what the player has just learned. Separately, the game leaned on extrinsic star ratings; adding an intrinsically satisfying ''aha'' to each solution keeps players who stop caring about stars."},{"heading":"Your turn","text":"Flow (anxiety / boredom / in-channel) or motivation (intrinsic / extrinsic)? (1) an expert grinding through beginner levels, (2) playing a level again just because the movement feels good, (3) a newcomer overwhelmed by a boss, (4) logging in only to keep a daily-reward streak, (5) challenge rising step by step to match a learning player. Answers: (1) boredom, (2) intrinsic, (3) anxiety, (4) extrinsic, (5) in-channel."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating flow as one fixed difficulty rather than a channel that must rise as skill grows. Mistake: assuming more extrinsic rewards always help — piling on points can crowd out intrinsic enjoyment. Exit: (a) A game that is far too easy for a skilled player produces which feeling? (b) Reading a rulebook for the sheer joy of the puzzle is which kind of motivation? Answers: boredom; intrinsic."}]}'::jsonb, 'Flow lives in the channel between anxiety (too hard) and boredom (too easy).', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which trio are the three load-bearing parts of a game?","options":["art, sound, story","rules, goals, feedback","levels, enemies, items","menus, saves, settings"],"answer":1,"explanation":"Rules constrain, goals motivate, feedback informs."},{"prompt":"In MDA, the layer a designer authors directly is…","options":["aesthetics","dynamics","mechanics","narrative"],"answer":2,"explanation":"Designers build mechanics; dynamics and aesthetics emerge from them."},{"prompt":"Emergent strategies that appear only during play are…","options":["mechanics","dynamics","aesthetics","rules"],"answer":1,"explanation":"Dynamics are the run-time behavior of mechanics under player input."},{"prompt":"A player whose skill far exceeds the challenge tends to feel…","options":["flow","anxiety","boredom","tension"],"answer":2,"explanation":"Too little challenge for the skill produces boredom."},{"prompt":"Replaying a level purely because the controls feel good is…","options":["extrinsic motivation","intrinsic motivation","a difficulty spike","a dominant strategy"],"answer":1,"explanation":"The activity is its own reward — intrinsic."},{"prompt":"The short act → feedback → decide cycle players repeat is the…","options":["tech tree","core loop","win condition","flow channel"],"answer":1,"explanation":"The core loop is the moment-to-moment engine of play."}]}'::jsonb, null, 8),
  (6, 'Balancing and difficulty curves', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read a difficulty curve, spot a spike, and recognize a dominant strategy that quietly kills a game''s balance. Warm-up: think of a game option that was so good you never picked anything else — what did that do to your choices?"},{"heading":"The idea","text":"*Balance* is not about making everything equal; it is about keeping *choices meaningful*. A game is well balanced when different options are viable in different situations, so the player has real decisions to make. The enemy of balance is a *dominant strategy* — an option that is at least as good as every alternative in every situation, so rational players always pick it and every other choice becomes dead weight. Separately, the *difficulty curve* is how challenge rises over the whole game. Ideally it climbs smoothly, roughly tracking the player''s growing skill (this is where balancing meets flow). A *difficulty spike* is a sudden jump that outruns the player''s skill and knocks them out of flow; a *difficulty valley* is a slump where the game gets too easy and drags."},{"heading":"Worked example","text":"A strategy game gives every unit a cost and a strength. Playtesters discover the archer is cheap *and* strong *and* ranged, so it beats everything — a textbook dominant strategy. The fix is not to delete the archer but to introduce *tradeoffs*: make archers weak in melee so cavalry counters them, so now the best choice *depends on* the opponent, restoring meaningful decisions (this is the rock-paper-scissors idea). Now improve a curve: a platformer''s level 5 boss makes 80 percent of testers quit while levels 1-4 were trivial. That is a spike after a valley. The improvement is to redistribute challenge — seed harder obstacles earlier and give the boss a readable attack pattern — so the curve climbs steadily instead of lurching."},{"heading":"Your turn","text":"Balance term for each: (1) one weapon is so strong nobody uses the others, (2) level 3 is suddenly far harder than 2 and 4, (3) rock beats scissors, scissors beats paper, paper beats rock, (4) a stretch of levels that feels too easy and boring, (5) two units cost the same but each wins in different situations. Answers: (1) dominant strategy, (2) difficulty spike, (3) balanced counters / meaningful tradeoffs, (4) difficulty valley, (5) balanced (viable choices)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking balance means every option is identical in power — it means every option has a situation where it is the right call. Mistake: fixing a dominant strategy by deleting the option instead of adding a tradeoff or counter. Exit: (a) What do we call an option that is always at least as good as all others? (b) A sudden challenge jump that outruns player skill is a difficulty…? Answers: a dominant strategy; spike."}]}'::jsonb, 'Balance = meaningful choices; a dominant strategy is the enemy of balance.', 13),
  (7, 'Prototyping and playtesting', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build a cheap prototype aimed at a single question and run a playtest that gathers behavior instead of opinions. Warm-up: if you had one afternoon to find out whether your game idea is fun, would you polish the art or hand a rough version to a stranger?"},{"heading":"The idea","text":"A *prototype* is the fastest, cheapest thing that can answer a specific design question — often paper, cards, or a few gray boxes, not finished art. Its job is to test an idea before you invest in building it. *Playtesting* is watching real players use your game to learn what actually happens, as opposed to what you assumed. The golden rule is to *watch behavior, not collect opinions*: where players hesitate, misread a rule, or give up tells you far more than ''did you like it?''. And crucially — you are not the player. Because you built the game you already know the rules and the trick, so your own play cannot reveal what a newcomer will find confusing. Test *early*, test *often*, and change one thing at a time so you know what caused a difference."},{"heading":"Worked example","text":"You suspect a card game''s turns take too long. Instead of coding a polished app, you print the cards and play with friends this afternoon — a paper prototype answering exactly one question: ''is the turn length a problem?'' During the playtest you *watch*: three players re-read the same card every turn and pause for ages. A weak designer asks ''was it too slow?'' and hears a polite ''it was fine''. A strong designer notes the *behavior* — repeated re-reading — and improves the mechanic by printing the key number larger and cutting one sub-step, then playtests again to confirm turns sped up. One question, one change, observed results."},{"heading":"Your turn","text":"Good practice or mistake? (1) building full 3-D art before testing whether the core loop is fun, (2) handing a paper version to a stranger and staying silent while they play, (3) asking testers ''did you like it?'' as your main data, (4) changing five rules at once between tests, (5) noticing exactly where players get stuck and fixing that one spot. Answers: (1) mistake, (2) good practice, (3) mistake, (4) mistake, (5) good practice."},{"heading":"Common mistakes & exit ticket","text":"Mistake: polishing before validating — expensive art on an unfun loop is wasted work. Mistake: trusting your own playthrough, since you already know the solution and cannot feel a newcomer''s confusion. Exit: (a) In a playtest, what should you value more — what players *say* or what they *do*? (b) What is the point of a prototype? Answers: what they do (behavior); to answer a specific design question cheaply before building."}]}'::jsonb, 'Prototype to answer one question; playtest by watching, not asking.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"core loop","translation":"the short, repeated cycle of action, feedback, and decision at the heart of play","example":"In a shooter the core loop is aim, fire, react, reposition."},{"term":"mechanics","translation":"the rules and systems a designer authors directly — the pieces, numbers, and allowed actions","example":"Drawing a card each turn is a mechanic."},{"term":"dynamics","translation":"the run-time behavior and strategies that emerge when players interact with the mechanics","example":"Bluffing and alliance-forming are dynamics, not written rules."},{"term":"aesthetics","translation":"the emotional responses a game evokes, such as tension, discovery, or triumph","example":"The suspense of a thinning deck is an aesthetic."},{"term":"flow","translation":"the absorbed state where challenge and player skill stay balanced, between boredom and anxiety","example":"A curve that rises with skill keeps players in flow."},{"term":"dominant strategy","translation":"an option always at least as good as every alternative, which erases meaningful choice","example":"An overpowered unit becomes a dominant strategy nobody plays around."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A well-balanced game mainly preserves…","options":["equal power for every option","meaningful choices among viable options","the longest possible play time","a single best strategy"],"answer":1,"explanation":"Balance keeps different options worth choosing in different situations."},{"prompt":"A sudden jump in challenge that knocks players out of flow is a…","options":["difficulty valley","difficulty spike","core loop","dominant strategy"],"answer":1,"explanation":"A spike outruns the player''s current skill."},{"prompt":"The best cure for a dominant strategy is usually to…","options":["delete the option entirely","add a tradeoff or counter so its value depends on the situation","make every option identical","hide it from players"],"answer":1,"explanation":"Tradeoffs and counters restore meaningful decisions."},{"prompt":"The main purpose of a prototype is to…","options":["show off finished art","answer a specific design question cheaply before building","market the game early","replace playtesting"],"answer":1,"explanation":"Prototypes test an idea fast and cheap."},{"prompt":"In a playtest you should value most…","options":["what players say they liked","what players actually do","your own opinion","the number of testers"],"answer":1,"explanation":"Behavior reveals problems that polite opinions hide."},{"prompt":"You are a poor test of your own game''s clarity because…","options":["you play too slowly","you already know the rules and solution, so you can''t feel a newcomer''s confusion","you dislike your own work","you never make mistakes"],"answer":1,"explanation":"Designers can''t un-know how their game works."}]}'::jsonb, null, 8),
  (10, 'Applied project: design a simple game on paper', 'writing', '{"sections":[{"heading":"The task","text":"Design a small game that could be played on paper or with everyday objects (cards, dice, a grid). You will not build a polished version — you''ll specify it precisely enough that a stranger could play it, using the vocabulary from this course."},{"heading":"Milestones","text":"1) Rules: write the allowed actions and constraints clearly. 2) Core loop: describe the short act → feedback → decide cycle a player repeats. 3) Win condition: state exactly how a player wins or how the game ends and is scored. 4) One balance concern: name a mechanic you suspect could become a dominant strategy or cause a difficulty spike, and how you''d playtest for it."},{"heading":"Self-check rubric","text":"✔ A stranger could follow your rules without asking you questions. ✔ Your core loop is a genuine cycle, not just a list of actions. ✔ The win condition is unambiguous and quantifiable. ✔ You identified a real balance risk and named a concrete playtest (watch behavior, change one thing) to check it. If all four are true, you''ve designed like a game designer."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000011' and l.position = v.pos
);
